(()=>{
 const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
 const dialog=$('#menu-dialog'),menuButton=$('.menu-button');
 if(dialog&&menuButton){
  if(!document.body.classList.contains('point-story')){menuButton.addEventListener('click',()=>dialog.showModal());$('.menu-close')?.addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>menuButton.focus());dialog.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>dialog.close()));}
  new MutationObserver(()=>menuButton.setAttribute('aria-expanded',String(dialog.open))).observe(dialog,{attributes:true,attributeFilter:['open']});
 }
 const codeTabs=$$('[data-code-tab]');
 if($$('[data-billing]').length){
  const pricingData=fetch('/pricing-data.json').then(r=>{if(!r.ok)throw Error();return r.json()});let period='month',config=null;
  document.addEventListener('click',event=>{const checkout=event.target.closest('[data-plan-checkout]');if(!checkout)return;const card=checkout.closest('[data-plan-card]'),input=card.querySelector('[data-plan-seats]');if(input&&Number(input.value)>Number(input.min))checkout.href='https://verse.ctruh.com/pricing?period='+period+'#plans'});
  let currency='USD';try{if(localStorage.getItem('verse-currency')==='INR')currency='INR'}catch(e){}
  const usd=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value);
  const money=value=>currency==='INR'?new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Math.round(value*((config&&config.inrPerUsd)||90))):usd(value);
  const sourceNote=$('.source-note');const sourceNoteUsd=sourceNote?sourceNote.textContent:'';
  function updatePlans(){if(!config)return;$$('[data-plan-card]').forEach(card=>{const id=card.dataset.planCard,p=config.plans[id],input=card.querySelector('[data-plan-seats]'),count=input?Math.min(500,Math.max(p.included,Math.floor(Number(input.value)||p.included))):p.included,factor=period==='year'?config.annualMonths:1,total=(p.price+Math.max(0,count-p.included)*p.extra)*factor,display=money(total);card.querySelector('[data-plan-price]').textContent=display;card.querySelector('[data-plan-price]').classList.toggle('wide-price',display.length>6);card.querySelector('[data-plan-period]').textContent=id==='free'?'Free forever':period==='year'?'/ year':'/ month';card.querySelector('[data-billing-note]').textContent=id==='free'?'':period==='year'?'≈ '+money(Math.round(total/12))+' a month, 2 months free'+(currency==='INR'?' · billed '+usd(total)+' in USD':''):(currency==='INR'?'Billed monthly in USD ('+usd(total)+')':'Billed monthly');if(input){card.querySelector('[data-seat-note]').textContent=p.included+' included, then '+money(p.extra*factor)+' / seat / '+(period==='year'?'year':'month');card.querySelector('[data-plan-checkout]').href='https://verse.ctruh.com/pricing?plan='+id+'&period='+period;card.querySelectorAll('.check-list li').forEach(li=>{if(li.textContent.includes('seats, more at'))li.textContent=p.included+' seats, more at '+money(p.extra*factor)+' / seat / '+(period==='year'?'year':'month')});}});}
  function paintCurrency(){$$('[data-currency]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.currency===currency)));if(sourceNote)sourceNote.textContent=currency==='INR'?'Prices in rupees are an approximate conversion at ₹'+((config&&config.inrPerUsd)||90)+' per US$1 and are for reference. You are billed in USD; taxes are calculated at checkout and final seats and payment are confirmed on Verse.':sourceNoteUsd}
  $$('[data-currency]').forEach(button=>button.addEventListener('click',()=>{currency=button.dataset.currency;try{localStorage.setItem('verse-currency',currency)}catch(e){}paintCurrency();updatePlans()}));
  pricingData.then(data=>{config=data;paintCurrency();updatePlans()}).catch(()=>{});
  $$('[data-billing]').forEach(button=>button.addEventListener('click',()=>{period=button.dataset.billing;$$('[data-billing]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));updatePlans()}));
  $$('[data-plan-seats]').forEach(input=>{input.addEventListener('input',updatePlans);input.addEventListener('change',()=>{input.value=String(Math.min(500,Math.max(Number(input.min),Math.floor(Number(input.value)||Number(input.min)))));updatePlans()})});
 }
 $$('[data-copy-hash]').forEach(button=>button.addEventListener('click',async()=>{const row=button.closest('.hash-row');try{await navigator.clipboard.writeText(row.querySelector('code').textContent);row.querySelector('.hash-status').textContent='Checksum copied.'}catch{row.querySelector('.hash-status').textContent='Select and copy the checksum with your keyboard.'}}));
 if(codeTabs.length){
  const samples=fetch('/code-samples.json').then(r=>{if(!r.ok)throw Error();return r.json()});let serial=0;
  async function selectCode(tab,focus=false){const request=++serial;try{const data=await samples;if(request!==serial)return;codeTabs.forEach(b=>{b.setAttribute('aria-selected',String(b===tab));b.tabIndex=b===tab?0:-1});$('#developer-code').textContent=data[tab.dataset.codeTab];$('#code-panel').setAttribute('aria-labelledby',tab.id);if(focus)tab.focus();$('.copy-status').textContent='';}catch{$('.copy-status').textContent='The other examples could not be loaded. Please try again.'}}
  codeTabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectCode(tab));tab.addEventListener('keydown',e=>{let n;if(e.key==='Home')n=0;else if(e.key==='End')n=codeTabs.length-1;else if(e.key==='ArrowRight')n=(index+1)%codeTabs.length;else if(e.key==='ArrowLeft')n=(index+codeTabs.length-1)%codeTabs.length;else return;e.preventDefault();selectCode(codeTabs[n],true)})});
  $('[data-copy-code]').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#developer-code').textContent);$('.copy-status').textContent='Code copied.'}catch{$('.copy-status').textContent='Select the code and copy it with your keyboard.'}});
 }
 $$('[data-copy-local]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.closest('.doc-code').querySelector('code').textContent);button.textContent='Copied ✓'}catch{button.textContent='Select code to copy'}}));
 const aboutTabs=$$('[data-about-tab]');
 function selectAbout(key,focus=false){aboutTabs.forEach(tab=>{const active=tab.dataset.aboutTab===key;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;document.getElementById(tab.getAttribute('aria-controls')).hidden=!active;if(active&&focus)tab.focus()});}
 if(aboutTabs.length){selectAbout(location.hash==='#verse-engine'?'verse-engine':'ctruh');aboutTabs.forEach((tab,index)=>{function activate(focus=false){selectAbout(tab.dataset.aboutTab,focus);history.replaceState(null,'',location.pathname+(tab.dataset.aboutTab==='verse-engine'?'#verse-engine':'#ctruh'))}tab.addEventListener('click',()=>activate());tab.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?1:1-index;aboutTabs[next].click();aboutTabs[next].focus()}})});window.addEventListener('hashchange',()=>selectAbout(location.hash==='#verse-engine'?'verse-engine':'ctruh'));}
 const searches=$$('[data-doc-search]');searches.forEach(input=>input.addEventListener('input',()=>{const query=input.value.trim().toLowerCase();searches.forEach(other=>{if(other!==input)other.value=input.value});$$('.docs-nav-content').forEach(nav=>{let count=0;nav.querySelectorAll('[data-doc-item]').forEach(a=>{a.hidden=!a.dataset.docTitle.includes(query);if(!a.hidden)count++});nav.querySelectorAll('section').forEach(section=>section.hidden=![...section.querySelectorAll('a')].some(a=>!a.hidden));nav.querySelector('.docs-no-results').hidden=count>0});if(query&&input.closest('.docs-mobile'))input.closest('.docs-mobile').querySelector('details').open=true}));
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&searches.length){e.preventDefault();searches.find(input=>input.offsetParent!==null)?.focus()}});
 $$('[data-feedback]').forEach(button=>button.addEventListener('click',()=>{let saved=false;try{localStorage.setItem('verse-doc-feedback:'+location.pathname,button.dataset.feedback);saved=true}catch{}$$('[data-feedback]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$('.doc-feedback p').textContent=saved?'Thank you. Your feedback is saved on this device.':'Thank you for your feedback.'}));
 $$('[data-email-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const fields=[...new FormData(form).entries()].map(([k,v])=>k[0].toUpperCase()+k.slice(1)+': '+v).join('\n');location.href='mailto:hello@ctruh.com?subject='+encodeURIComponent(form.dataset.emailForm)+'&body='+encodeURIComponent(fields)}));
})();
